const COMPONENT_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const sumBasePremiums = (items: { type: string }[]): number => {
  const runeCount = items.filter((item) => item.type === "rune").length;
  const runeTotal =
    runeCount === COMPONENT_BLOCK_SIZE
      ? COMPONENT_BLOCK_PREMIUM
      : runeCount * COMPONENT_PREMIUM;
  const otherTotal = items
    .filter((item) => item.type !== "rune")
    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
  return runeTotal + otherTotal;
};

