10	
11	const BASE_PREMIUM: Record<string, number> = {
12	  sword: 100,
13	  amulet: 60,
14	  staff: 80,
15	  potion: 40,
16	};
17	
18	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
19	const PROCESSING_FEE = 5;
20	
21	const COMPONENT_TYPE = "rune";
22	const COMPONENT_PREMIUM = 25;
23	const COMPONENT_BLOCK_SIZE = 3;
24	const COMPONENT_BLOCK_PREMIUM = 60;
25	
26	const isComponent = (item: { type: string }): boolean =>
27	  item.type === COMPONENT_TYPE;
28	
29	const sumComponentPremium = (componentCount: number): number =>
30	  componentCount === COMPONENT_BLOCK_SIZE
31	    ? COMPONENT_BLOCK_PREMIUM
32	    : componentCount * COMPONENT_PREMIUM;
33	
34	const sumBasePremiums = (items: { type: string }[]): number => {
35	  const componentCount = items.filter(isComponent).length;
36	  const nonComponentTotal = items
37	    .filter((item) => !isComponent(item))
38	    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
39	  return sumComponentPremium(componentCount) + nonComponentTotal;
40	};
41	
42	const quotePremium = (step: QuoteStep): number => {
43	  const itemsTotal = sumBasePremiums(step.items);
44	  const firstInsuranceSurcharge = itemsTotal * FIRST_INSURANCE_SURCHARGE_RATE;
45	  const premium = itemsTotal + firstInsuranceSurcharge + PROCESSING_FEE;
46	  return Math.ceil(premium);
47	};

