interface QuoteStep {
  op: "quote";
  items: { type: string }[];
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const PROCESSING_FEE = 5;

const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const isComponent = (item: { type: string }): boolean =>
  COMPONENT_TYPES.includes(item.type);

const sumComponentPremium = (count: number): number =>
  count === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM
    : count * COMPONENT_PREMIUM;

const countByType = (items: { type: string }[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const sumBasePremiums = (items: { type: string }[]): number => {
  let total = 0;
  for (const [type, count] of countByType(items)) {
    total += isComponent({ type })
      ? sumComponentPremium(count)
      : BASE_PREMIUM[type] * count;
  }
  return total;
};

const quotePremium = (step: QuoteStep): number => {
  const itemsTotal = sumBasePremiums(step.items);
  const firstInsuranceSurcharge = itemsTotal * FIRST_INSURANCE_SURCHARGE_RATE;
  const premium = itemsTotal + firstInsuranceSurcharge + PROCESSING_FEE;
  return Math.ceil(premium);
};

export const runScenario = (scenario: Scenario): unknown => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step),
  }));
  return { results };
};

