import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Edge case: empty item list ---
  it("empty item list → premium 5 G (only processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });
    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Base premiums for main items (single item, newcomer: +10% first insurance, +5 fee) ---
  it("single plain sword, no history → base 100 + 10 first + 5 fee = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("single plain amulet, no history → base 60 + 6 first + 5 fee = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("single plain staff, no history → base 80 + 8 first + 5 fee = 93 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("single plain potion, no history → base 40 + 4 first + 5 fee = 49 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Components and building blocks ---
  it("2 runes → base 50 G → premium 50*1.1 + 5 = 60 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });
    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes → base 60 G (block applies) → premium 60*1.1 + 5 = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("4 runes → base 100 G (no block) → premium 100*1.1 + 5 = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
          ],
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes → base 175 G (no block) → premium 175*1.1 + 5 = 198 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: Array.from({ length: 7 }, () => ({ type: "rune" })),
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 198 }] });
  });
  it("2 runes + 1 moonstone → base 75 G (no block) → premium 75*1.1 + 5 = 88 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 88 }] });
  });
  it("3 runes + 3 moonstones → base 120 G (two blocks) → premium 120*1.1 + 5 = 137 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "moonstone" },
            { type: "moonstone" },
            { type: "moonstone" },
          ],
        },
      ],
    });
    expect(result).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Item-specific modifiers in isolation ---
  it("cursed sword → 100 base + 50 curse + 10 first + 5 fee = 165 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword", cursed: true }] }],
    });
    expect(result).toEqual({ results: [{ premium: 165 }] });
  });
  it("sword ench 5 → 100 base + 30 high-ench + 10 first + 5 fee = 145 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword", enchantment: 5 }] }],
    });
    expect(result).toEqual({ results: [{ premium: 145 }] });
  });
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both curse and high-enchantment surcharges apply");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years → 20% loyalty discount applies to policy base");
  it.todo("follow-up contract (second quote in scenario) → 15% discount on policy base");

  // --- Modifier scope on multi-item policy ---
  it.todo("cursed sword + plain amulet → policy base 160, curse adds 50 (of sword base) → 210 before fee");

  // --- Rounding ---
  it.todo("premium yielding 197.5 G → 198 G (rounded up, MHPCO favor)");
  it.todo("payout yielding 350.5 G → 350 G (rounded down, MHPCO favor)");

  // --- Integration examples (full premium) ---
  it.todo("newcomer with cursed sword (ench 3) → premium 165 G");
  it.todo("long-standing (3y) customer's second contract, cursed sword ench 7 → premium 160 G");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel, ench 3), damage 500 → payout 400 (full minus 100 deductible)");
  it.todo("damage to a rune (value 250), damage 200 → payout 100 (full minus 100 deductible)");

  // --- Claim: enchantment threshold vs dragon material ---
  it.todo("dragon sword ench 8, damage 1000 → payout 400 (50% then deductible)");
  it.todo("dragon sword ench 9, damage 1000 → payout 400 (both apply, 50% wins, then deductible)");
  it.todo("dragon sword ench 5, damage 800 → payout 700 (dragon full, then deductible)");
  it.todo("steel sword ench 9, damage 1000 → payout 400 (high-enchantment 50%, then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damages sword (500) and amulet (300) → payout 600 (deductible per item)");

  // --- Claim: multiple items of same type ---
  it.todo("two swords policy → insurance sum 2000, cap 4000; two sword damages each own deductible");
  it.todo("more sword damages than swords insured → claim rejected (non-zero exit)");

  // --- Claim: cap exhaustion ---
  it.todo("sword + amulet policy → insurance sum 1600, cap 3200");
  it.todo("cursed sword (modified premium 165) → cap 2000 (based on unmodified insurance value)");
  it.todo("sword + 3 runes block → insurance sum 1750 (block affects premium only, not sum)");
  it.todo("sword cap 2000, two 1500 claims → first payout 1400 (cap left 600), second payout 600 (cap left 0)");

  // --- Edge cases: errors ---
  it.todo("quote with unknown item type → non-zero exit, error to stderr, no results to stdout");
  it.todo("claim references item not in policy → non-zero exit, error to stderr");
  it.todo("claim with negative damage amount → non-zero exit, error to stderr");
});

