const insuranceSumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUE[item.type], 0);

const payoutForDamage = (damage: Damage): number =>
  Math.max(0, damage.amount - DEDUCTIBLE);

const processClaim = (
  step: ClaimStep,
  policy: QuoteStep,
): { payout: number; remainingCap: number } => {
  const cap = CAP_MULTIPLIER * insuranceSumOf(policy.items);
  const payout = step.incident.damages.reduce(
    (sum, damage) => sum + payoutForDamage(damage),
    0,
  );
  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): unknown => {
  const policies: QuoteStep[] = [];
  let quoteCount = 0;
  const results = scenario.steps.map((step) => {
    if (step.op === "quote") {
      const isFollowUp = quoteCount > 0;
      quoteCount += 1;
      policies.push(step);
      return { premium: quotePremium(step, scenario.customer, isFollowUp) };
    }
    const policy = scenario.steps[step.policy] as QuoteStep;
    return processClaim(step, policy);
  });
  return { results };
};

