const capFor = (policy: QuoteStep): number =>
  CAP_MULTIPLIER * insuranceSumOf(policy.items);

const processClaim = (
  step: ClaimStep,
  policy: QuoteStep,
  remainingCap: number,
): { payout: number; remainingCap: number } => {
  const desired = Math.floor(sumClaimPayout(step, policy));
  const payout = Math.min(desired, remainingCap);
  return { payout, remainingCap: remainingCap - payout };
};

export const runScenario = (scenario: Scenario): unknown => {
  const remainingCapByPolicy = new Map<number, number>();
  let quoteCount = 0;
  const results = scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      const isFollowUp = quoteCount > 0;
      quoteCount += 1;
      remainingCapByPolicy.set(index, capFor(step));
      return { premium: quotePremium(step, scenario.customer, isFollowUp) };
    }
    const policy = scenario.steps[step.policy] as QuoteStep;
    const remainingCap =
      remainingCapByPolicy.get(step.policy) ?? capFor(policy);
    const result = processClaim(step, policy, remainingCap);
    remainingCapByPolicy.set(step.policy, result.remainingCap);
    return result;
  });
  return { results };
};

