167	// Resolve the insured item for a damage, then compute its payout.
168	const payoutForClaimDamage = (damage: Damage, policy: QuoteStep): number =>
169	  payoutForDamage(damage, insuredItemFor(damage, policy));
170	
171	const sumClaimPayout = (step: ClaimStep, policy: QuoteStep): number =>
172	  step.incident.damages.reduce(
173	    (sum, damage) => sum + payoutForClaimDamage(damage, policy),
174	    0,
175	  );
176	
177	const capFor = (policy: QuoteStep): number =>
178	  CAP_MULTIPLIER * insuranceSumOf(policy.items);
179	
180	const processClaim = (
181	  step: ClaimStep,
182	  policy: QuoteStep,
183	  remainingCap: number,
184	): { payout: number; remainingCap: number } => {
185	  const desired = Math.floor(sumClaimPayout(step, policy));
186	  const payout = Math.min(desired, remainingCap);
187	  return { payout, remainingCap: remainingCap - payout };
188	};
189	
190	// Mutable state threaded through the steps of a single scenario run:
191	// how many quotes have been seen (for the follow-up discount) and the
192	// unused payout cap still available on each policy.
193	interface ScenarioState {
194	  quoteCount: number;
195	  remainingCapByPolicy: Map<number, number>;
196	}
197	
198	const handleQuote = (
199	  step: QuoteStep,
200	  index: number,
201	  customer: Customer,
202	  state: ScenarioState,
203	): unknown => {
204	  const isFollowUp = state.quoteCount > 0;
205	  state.quoteCount += 1;
206	  state.remainingCapByPolicy.set(index, capFor(step));
207	  return { premium: quotePremium(step, customer, isFollowUp) };
208	};
209	
210	const handleClaim = (
211	  step: ClaimStep,
212	  steps: Step[],
213	  state: ScenarioState,
214	): unknown => {
215	  const policy = steps[step.policy] as QuoteStep;
216	  const remainingCap =
217	    state.remainingCapByPolicy.get(step.policy) ?? capFor(policy);
218	  const result = processClaim(step, policy, remainingCap);
219	  state.remainingCapByPolicy.set(step.policy, result.remainingCap);
220	  return result;
221	};
222	
223	export const runScenario = (scenario: Scenario): unknown => {
224	  const state: ScenarioState = {
225	    quoteCount: 0,
226	    remainingCapByPolicy: new Map<number, number>(),
227	  };
228	  const results = scenario.steps.map((step, index) =>
229	    step.op === "quote"
230	      ? handleQuote(step, index, scenario.customer, state)
231	      : handleClaim(step, scenario.steps, state),
232	  );
233	  return { results };
234	};

